"""Searchable local help with no network or hardware side effects."""
from PySide6.QtCore import Qt
from PySide6.QtWidgets import QDialog,QVBoxLayout,QHBoxLayout,QComboBox,QLineEdit,QPlainTextEdit,QLabel
from . import __version__

TOPICS = {
    'Getting started': 'Extract the source ZIP into a new folder. On Windows run Setup.bat, then Start.bat. Setup supports standard 64-bit CPython 3.10–3.14. Debug-Launch.bat keeps launch errors visible.\n\nConnect the device by USB, close other serial tools, refresh ports and select the correct port. Connect opens only the serial transport; it does not verify Flipper identity. CLI and UART Bridge use different device configurations. No device commands are sent automatically. To query device name/firmware/hardware, use Identify / Refresh device in Device Dashboard after connecting in CLI mode. Console Send pauses while querying; Disconnect cancels. No SD-card or Wi-Fi board query is performed.',
    'Keyboard shortcuts': 'F1: Help Center\nF5: Refresh ports while disconnected\nCtrl+Home: Home / GPIO Lab\nCtrl+L: UART Console input\nCtrl+,: Appearance\nAlt+Left / Alt+Right: Back / Forward\nCtrl+1..9: Workspace tabs from left to right (Ctrl+9: SD File Manager)\n\nIn command input, Up/Down recalls successfully queued commands. Down past the newest restores your draft. Press Enter or Send to transmit; recall never transmits.',
    'Console and logs': 'UART Console supports explicit text sends with CRLF, LF or no line ending. Command history holds 100 entries in memory. Transcript search wraps through matches; turn Auto scroll off to read older text.\n\nLive Log combines case-insensitive text and severity filters. Export log includes all retained entries; Export visible and Copy visible include the filtered view. Clear log removes all retained entries. Up to 1000 entries are kept during this session.',
    'Presets and backups': 'GPIO presets store pin selection and notes locally. New clears the editor; Duplicate copies saved fields to a unique name. To Rename, select a saved preset and type a unique new name. Save Setup stores current editor contents.\n\nBackup & Tools exports/restores settings backups up to 5 MB. Restore replaces saved presets and included preferences after validation and confirmation. Export a current backup before restoring for rollback. Connections, transcripts and command history are excluded.',
    'SD Backup & Restore': 'Identify in CLI mode, probe SD Files, then open Backup & Tools. Back up /ext or the current folder to a unique local backup. Limits: 4 MiB/file, 256 MiB total, 2,000 entries; nothing is skipped. Completed backups include a verified SHA-256 manifest. Incomplete backups cannot be restored. Choose a completed backup and a NEW /ext folder name; Verify & preview then explicitly confirm. All payloads and the manifest are revalidated. No merge, existing-file overwrite or formatting is offered. Restored files do not automatically replace active app data. Stop other device writes before a snapshot. Cancel disconnects and may leave incomplete local data or a partial new SD folder. Physical backup/recovery remains unverified.',
    'SD File Manager': 'Connect in CLI mode, identify in Device Dashboard, then SD Files → Refresh / Probe SD. An installed, mounted SD card is required. Double-click folders to browse. Transfers are limited to 4 MiB with integrity checks. Uploads refuse existing remote names; downloads replace the chosen local file only after verification. Delete confirms one file or empty folder; no root, recursive delete or formatting. Cancel & disconnect and storage errors close the session; reconnect, identify and probe again. Interrupted uploads may leave .pd-upload-*.part or a new partial destination. Inspect before cleanup. Device-side work can finish after disconnect.',
    'IR Workspace': 'Open local .ir files, filter/select signals, save/load/rename/remove named libraries, and export whole files or one signal. Local actions never transmit. Libraries are limited to ten and 2 MB total text, and are excluded from settings backups; export .ir files separately.\n\nIdentify in CLI mode, then Check IR support. Select a valid signal, Transmit selected signal and explicitly confirm. No SD card is required. One ir tx command is sent; firmware may emit normal protocol repeat frames. A completed command does not verify appliance reception. Cancellation disconnects and cannot recall emitted IR.\n\nParsed addresses/commands use four little-endian hex bytes and protocol bit ranges. Raw CLI limits: 512 timings, two seconds total, integer-percent duty, 960 command characters. Valid files outside CLI limits remain saveable/exportable; hover Transmit for the reason it is disabled. Physical IR behavior remains unverified.',
    'Troubleshooting': 'No ports: check the USB data cable, device, drivers and Refresh. Connection lost: reconnect USB, then Retry; the selected port must be present. Reconnect is manual and does not send commands.\nPort busy or connection error: close qFlipper and other serial programs, check USB, then Retry. Full error text is available on hover and in Live Log.\nCorrupt preset store: existing data is preserved. Restore a valid settings backup before saving or importing presets.\nExport failed: verify destination access and free space. Existing destination files are preserved if replacement fails.\nWorkspace: Ctrl+K opens the workspace selector; Ctrl+F opens transcript search; Ctrl+L focuses the command draft. Drag GPIO panel dividers to resize them; Ctrl+Shift+0 resets panel sizes. Panel sizes are saved locally and are not included in settings backups.\nConsole: Save favorite stores the draft locally; Load never sends it. Pause display continues bounded capture; Resume catches up. Receive timestamps label serial chunks, which may split device lines. Plain text exports preserve received text; JSON includes receive times and retention status. Clear console clears retained capture too. Favorites and timestamp preferences are saved locally but are not included in the current settings backup format.\nUse Export diagnostic report in Backup & Tools for application/runtime versions and settings health without notes, serial text or raw error strings.',
    'Release and capabilities': 'v0.7.0 adds named IR libraries, stronger payload validation, export and confirmed single-command IR transmission. Identify the Flipper, then open SD Files and Refresh / Probe SD. In CLI mode, open Device Dashboard and click Identify / Refresh device. Device_info, SD file operations, bounded backups and supported IR transmission are implemented; identity is device-reported, not cryptographic authentication.\n\nAvailable: serial transport, local presets, appearance, navigation memory, console tools, logs, IR file inspection, settings backups and diagnostics.\n\nGPIO hardware reads/writes, app installation and battery telemetry require RC7 integration. Windows packaging was verified for v0.3.0. Physical hardware integration remains unverified.\n\nBuild-Windows.bat produces dist/PurpleDragonFlipperStudio/PurpleDragonFlipperStudio.exe. Distribute the entire folder including _internal. The source ZIP contains no prebuilt Windows executable.'}

class HelpCenter(QDialog):
    def __init__(self,parent=None):
        super().__init__(parent)
        self.setWindowTitle('Purple Dragon Help Center · '+__version__)
        self.setObjectName('helpCenter')
        self.setStyleSheet('QDialog#helpCenter { background: #060b18; }')
        self.resize(780,580)
        layout=QVBoxLayout(self)
        row=QHBoxLayout();self.search=QLineEdit();self.search.setPlaceholderText('Search all help topics…');self.search.setMaxLength(256)
        self.topic=QComboBox();self.topic.addItems(TOPICS);row.addWidget(self.search,1);row.addWidget(self.topic);layout.addLayout(row)
        self.text=QPlainTextEdit();self.text.setReadOnly(True);layout.addWidget(self.text)
        self.feedback=QLabel();layout.addWidget(self.feedback)
        self.search.textChanged.connect(self.render);self.topic.currentTextChanged.connect(self.render);self.render()
    def render(self,*_):
        query=self.search.text().strip().casefold()
        if query:
            matches=[name+'\n\n'+body for name,body in TOPICS.items() if query in (name+' '+body).casefold()]
            self.text.setPlainText('\n\n────────\n\n'.join(matches) if matches else 'No matching topics. Try a different search term.')
            self.feedback.setText(f'{len(matches)} matching topics');self.topic.setEnabled(False)
        else:
            self.topic.setEnabled(True);name=self.topic.currentText();self.text.setPlainText(name+'\n\n'+TOPICS[name]);self.feedback.setText('F1 opens this guide · Created by KyleAustin85')
